const std = @import("std");
const mem = std.mem;

pub const Node = struct {
    pub data: i32,
    pub left: ?*Node,
    pub right: ?*Node,
};

pub const Tree = struct {
    root: ?*Node,
    allocator: mem.Allocator,

    pub fn init(allocator: mem.Allocator) Tree {
        return Tree{
            .root = null,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Tree) void {
        destroyNode(self.root, self.allocator);
        self.root = null;
    }

    pub fn insert(self: *Tree, data: i32) mem.Allocator.Error!void {
        if (self.root) |root| {
            var current = root;
            while (true) {
                if (data <= current.data) {
                    if (current.left) |left| {
                        current = left;
                    } else {
                        const new_node = try self.allocator.create(Node);
                        new_node.* = Node{
                            .data = data,
                            .left = null,
                            .right = null,
                        };
                        current.left = new_node;
                        return;
                    }
                } else {
                    if (current.right) |right| {
                        current = right;
                    } else {
                        const new_node = try self.allocator.create(Node);
                        new_node.* = Node{
                            .data = data,
                            .left = null,
                            .right = null,
                        };
                        current.right = new_node;
                        return;
                    }
                }
            }
        } else {
            const new_node = try self.allocator.create(Node);
            new_node.* = Node{
                .data = data,
                .left = null,
                .right = null,
            };
            self.root = new_node;
        }
    }

    pub fn sortedData(self: *const Tree, allocator: mem.Allocator) mem.Allocator.Error![]i32 {
        var list = std.ArrayList(i32).init(allocator);
        try collectSorted(self.root, &list);
        return list.toOwnedSlice();
    }

    fn destroyNode(node: ?*Node, allocator: mem.Allocator) void {
        if (node) |n| {
            destroyNode(n.left, allocator);
            destroyNode(n.right, allocator);
            allocator.destroy(n);
        }
    }

    fn collectSorted(node: ?*Node, list: *std.ArrayList(i32)) mem.Allocator.Error!void {
        if (node) |n| {
            try collectSorted(n.left, list);
            try list.append(n.data);
            try collectSorted(n.right, list);
        }
    }
};

Wait: In `collectSorted`, we pass `self.root` which is `?*Node`. The function signature takes `?*Node`. That's fine.

But we need to ensure `std.ArrayList(i32)` is correct. In Zig, `std.ArrayList` is a struct that takes a type parameter. So `std.ArrayList(i32)` is correct.

One more nuance: `list.toOwnedSlice()` returns `[]i32` and transfers ownership to caller. The caller (test) will free it with `allocator.free(actual)`. That's correct.

Now, check for any missing semicolons or syntax errors.

- `pub const Node = struct { ... };` okay.
- `pub const Tree = struct { ... };` okay.
